CREATE TABLE notification_activity (
            owner_bare_jid TEXT NOT NULL,
            conversation_jid TEXT NOT NULL,
            last_active_at_ms INTEGER NOT NULL,
            last_chat_state TEXT NULL CONSTRAINT notification_activity_last_chat_state_check CHECK (last_chat_state IS NULL OR last_chat_state IN ('active', 'composing', 'paused', 'inactive', 'gone')),
            last_read_at_ms INTEGER NULL,
            presence_show TEXT NULL CONSTRAINT notification_activity_presence_show_check CHECK (presence_show IS NULL OR presence_show IN ('away', 'chat', 'dnd', 'xa')),
            created_at_ms INTEGER NOT NULL,
            updated_at_ms INTEGER NOT NULL,
            PRIMARY KEY (owner_bare_jid, conversation_jid)
        );

CREATE TABLE notification_candidates (
            recipient_bare_jid TEXT NOT NULL,
            conversation_jid TEXT NOT NULL,
            sender_jid TEXT NOT NULL,
            thread_id TEXT NOT NULL DEFAULT '',
            stanza_id_by TEXT NOT NULL,
            stanza_id TEXT NOT NULL,
            class TEXT NOT NULL CONSTRAINT notification_candidates_class_check CHECK (class IN ('dm', 'dm_mention', 'personal_mention', 'channel_mention', 'active_channel_mention', 'notify_all')),
            reason TEXT NOT NULL CONSTRAINT notification_candidates_reason_check CHECK (reason IN ('offline_dm', 'offline_dm_mention', 'groupchat_personal_mention', 'groupchat_channel_mention', 'groupchat_active_channel_mention', 'groupchat_notify_all')),
            created_at_ms INTEGER NOT NULL,
            policy_error_count INTEGER NOT NULL DEFAULT 0,
            next_attempt_at_ms INTEGER,
            outboxed_at_ms INTEGER,
            suppressed_reason TEXT CONSTRAINT notification_candidates_suppressed_reason_check CHECK (suppressed_reason IS NULL OR suppressed_reason IN ('xep0357_self', 'xep0357_no_registration', 'xep0357_registration_disabled', 'xep0492_never', 'xep0492_on_mention_miss', 'xep0191_blocked', 'xep0513_noping', 'xep0513_active_miss', 'waddle_dnd', 'provider_rejected', 'provider_token_expired', 'xep0357_push_service_degraded', 'unread_zero_at_publish', 'policy_retries_exhausted', 'xep0444_reaction')),
            noping INTEGER NOT NULL DEFAULT 0,
            no_store INTEGER NOT NULL DEFAULT 0,
            no_permanent_store INTEGER NOT NULL DEFAULT 0,
            last_message_body TEXT,
            reaction INTEGER NOT NULL DEFAULT 0,
            delivery_id TEXT,
            quarantined_at_ms INTEGER,
            quarantined_suppressed_reason TEXT,
            PRIMARY KEY (recipient_bare_jid, conversation_jid, thread_id, stanza_id_by, stanza_id, class)
        );

CREATE TABLE notification_outbox (
            job_id TEXT PRIMARY KEY,
            recipient_bare_jid TEXT NOT NULL,
            push_service_jid TEXT NOT NULL,
            node TEXT NOT NULL,
            conversation_jid TEXT NOT NULL,
            sender_jid TEXT NOT NULL,
            sender_jids TEXT NOT NULL,
            thread_id TEXT NOT NULL DEFAULT '',
            class TEXT NOT NULL CONSTRAINT notification_outbox_class_check CHECK (class IN ('dm', 'dm_mention', 'personal_mention', 'channel_mention', 'active_channel_mention', 'notify_all')),
            message_count INTEGER NOT NULL,
            context_xml TEXT NOT NULL,
            -- #719 rich XEP-0357 §5.4 summary fields. Both nullable and
            -- written together: `summary_sender_jid` is the
            -- `last-message-sender` (present iff the recipient opted in),
            -- `summary_body` the (hint-stripped) `last-message-body`.
            -- Stored explicitly rather than inferred from the routing
            -- `sender_jid`, so `RichSummary` round-trips 1:1.
            summary_sender_jid TEXT,
            summary_body TEXT,
            approved_payload_xml TEXT,
            approved_publish_options_xml TEXT,
            queue_acceptance_may_exist INTEGER NOT NULL DEFAULT 1 CHECK (queue_acceptance_may_exist IN (0, 1)),
            status TEXT NOT NULL CHECK (status IN ('queued', 'in-progress', 'published', 'failed')),
            attempt_count INTEGER NOT NULL DEFAULT 0,
            policy_error_count INTEGER NOT NULL DEFAULT 0,
            last_error TEXT,
            next_attempt_at_ms INTEGER,
            claimed_at_ms INTEGER,
            claim_token TEXT,
            created_at_ms INTEGER NOT NULL,
            updated_at_ms INTEGER NOT NULL,
            published_at_ms INTEGER
        );

CREATE TABLE notification_outbox_lineage (candidate_delivery_id TEXT NOT NULL, job_id TEXT NOT NULL, settled_at_ms INTEGER, PRIMARY KEY (candidate_delivery_id, job_id));

CREATE TABLE notification_settings_projection (
                    owner_bare_jid TEXT NOT NULL,
                    conversation_jid TEXT NOT NULL,
                    conversation_kind TEXT NOT NULL CHECK (conversation_kind IN ('direct', 'private_group', 'public_group')),
                    mode TEXT NOT NULL CHECK (mode IN ('always', 'on-mention', 'never')),
                    rich_payload_opt_in INTEGER NOT NULL DEFAULT 0 CHECK (rich_payload_opt_in IN (0, 1)),
                    source_version INTEGER NOT NULL,
                    updated_at_ms INTEGER NOT NULL,
                    source_node TEXT NOT NULL,
                    source_item_id TEXT NOT NULL,
                    PRIMARY KEY (owner_bare_jid, conversation_jid)
                );

CREATE TABLE notification_settings_projection_source_version (
                    id INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
                    current_version INTEGER NOT NULL
                );

CREATE TABLE p21_receipt_operation_results (
    operation_id TEXT PRIMARY KEY NOT NULL,
    message_key TEXT NOT NULL,
    receipt_kind INTEGER NOT NULL,
    semantic_identity_hash BLOB NOT NULL CHECK (length(semantic_identity_hash) = 32),
    inserted INTEGER NOT NULL CHECK (inserted IN (0, 1))
);

CREATE TABLE pending_auth (
    state TEXT PRIMARY KEY,
    payload TEXT NOT NULL,
    expires_at_ms INTEGER NOT NULL
);

CREATE TABLE pending_delivery (
            row_id TEXT PRIMARY KEY,
            recipient_jid TEXT NOT NULL,
            original_receipt_at INTEGER NOT NULL,
            payload_kind TEXT NOT NULL,
            archive_stanza_by TEXT,
            archive_stanza_id TEXT,
            transient_xml TEXT,
            flushed_in_session TEXT,
            outbound_sequence INTEGER,
            notification_outboxed_at_ms INTEGER,
            claimed_at_ms INTEGER,
            claim_token TEXT,
            claim_offered INTEGER NOT NULL DEFAULT 0
        , origin_stream_id TEXT, inbound_seq INTEGER, pair_sequence INTEGER, notification_recovery_ordinal INTEGER CHECK (notification_recovery_ordinal IS NULL OR (typeof(notification_recovery_ordinal) = 'integer' AND notification_recovery_ordinal > 0)));

CREATE TABLE pending_delivery_sm_promotions (origin_stream_id TEXT NOT NULL, sequence BIGINT NOT NULL, created_at_ms BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (origin_stream_id, sequence));

CREATE TABLE pending_delivery_startup_migrations (name TEXT PRIMARY KEY, completed_at INTEGER NOT NULL);

CREATE TABLE pending_notification_recovery_counter (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), last_ordinal INTEGER NOT NULL CHECK (typeof(last_ordinal) = 'integer' AND last_ordinal >= 0));

CREATE TABLE permission_tuples (
    id TEXT PRIMARY KEY,
    object_type TEXT NOT NULL,
    object_id TEXT NOT NULL,
    relation TEXT NOT NULL,
    subject_type TEXT NOT NULL,
    subject_id TEXT NOT NULL,
    subject_relation TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    UNIQUE(object_type, object_id, relation, subject_type, subject_id, subject_relation)
);

CREATE TABLE private_xml_storage (
    jid TEXT NOT NULL,
    namespace TEXT NOT NULL,
    xml_content TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (jid, namespace)
);

CREATE TABLE provider_webhook_deliveries (
    provider_id TEXT NOT NULL,
    delivery_id TEXT NOT NULL,
    plugin_id TEXT NOT NULL,
    event_type TEXT NOT NULL,
