    status TEXT NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (provider_id, delivery_id)
);

CREATE TABLE pubsub_affiliations (
                    owner_jid TEXT NOT NULL,
                    node_name TEXT NOT NULL,
                    entity_jid TEXT NOT NULL,
                    affiliation TEXT NOT NULL,
                    updated_at_ms INTEGER NOT NULL,
                    PRIMARY KEY (owner_jid, node_name, entity_jid),
                    FOREIGN KEY (owner_jid, node_name)
                        REFERENCES pubsub_nodes(owner_jid, node_name)
                        ON DELETE CASCADE
                );

CREATE TABLE pubsub_items (
                    seq INTEGER PRIMARY KEY AUTOINCREMENT,
                    owner_jid TEXT NOT NULL,
                    node_name TEXT NOT NULL,
                    item_id TEXT NOT NULL,
                    payload_xml TEXT,
                    publisher_jid TEXT,
                    published_at_ms INTEGER NOT NULL,
                    UNIQUE (owner_jid, node_name, item_id),
                    FOREIGN KEY (owner_jid, node_name)
                        REFERENCES pubsub_nodes(owner_jid, node_name)
                        ON DELETE CASCADE
                );

CREATE TABLE pubsub_nodes (
                    owner_jid TEXT NOT NULL,
                    node_name TEXT NOT NULL,
                    access_model TEXT NOT NULL,
                    publish_model TEXT NOT NULL,
                    node_type TEXT,
                    max_items INTEGER NOT NULL,
                    persist_items INTEGER NOT NULL,
                    deliver_payloads INTEGER NOT NULL,
                    notify_retract INTEGER NOT NULL,
                    notify_delete INTEGER NOT NULL,
                    send_last_published_item TEXT NOT NULL,
                    created_at_ms INTEGER NOT NULL,
                    PRIMARY KEY (owner_jid, node_name)
                );

CREATE TABLE pubsub_owner_configured (owner_jid TEXT NOT NULL, node_name TEXT NOT NULL, PRIMARY KEY (owner_jid, node_name), FOREIGN KEY (owner_jid, node_name) REFERENCES pubsub_nodes(owner_jid, node_name) ON DELETE CASCADE);

CREATE TABLE pubsub_push_publications (service_jid TEXT NOT NULL, node_name TEXT NOT NULL, revision BIGINT NOT NULL CHECK (revision > 0), job_token TEXT NOT NULL, payload_hash TEXT NOT NULL, PRIMARY KEY (service_jid, node_name));

CREATE TABLE pubsub_schema_version (
                version INTEGER NOT NULL PRIMARY KEY
            );

CREATE TABLE pubsub_subscriptions (
                    owner_jid TEXT NOT NULL,
                    node_name TEXT NOT NULL,
